double f = 0.3048;
string famName = Tama.Args.Get(args, "family", "");
string lvlName = Tama.Args.Get(args, "level", "");
var only = (args.ContainsKey("only") && args["only"] is object[] oa) ? oa.Select(o => o.ToString()).ToList() : new List<string>();
var level = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().First(l => l.Name == lvlName);
var sym = new FilteredElementCollector(doc).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().First(s => s.Family.Name == famName);
if (!sym.IsActive) { sym.Activate(); doc.Regenerate(); }
double lz = level.Elevation * f;
var existingMarks = new FilteredElementCollector(doc).OfClass(typeof(FamilyInstance)).Cast<FamilyInstance>()
    .Where(fi => fi.Symbol.Family.Name == famName).Select(fi => fi.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.AsString()).ToList();
var outp = new List<object>();
foreach (var row in (object[])args["columns"]) {
  var r = (object[])row; string id = r[0].ToString();
  if (only.Count > 0 && !only.Contains(id)) continue;
  if (existingMarks.Contains(id)) { outp.Add(new { id, skipped = "already placed" }); continue; }
  double x = Convert.ToDouble(r[1]), y = Convert.ToDouble(r[2]), zb = Convert.ToDouble(r[3]), zt = Convert.ToDouble(r[4]), ang = Convert.ToDouble(r[5]);
  var pt = new XYZ(x / f, y / f, level.Elevation);
  var fi = doc.Create.NewFamilyInstance(pt, sym, level, Autodesk.Revit.DB.Structure.StructuralType.Column);
  fi.get_Parameter(BuiltInParameter.FAMILY_TOP_LEVEL_PARAM).Set(level.Id);
  fi.get_Parameter(BuiltInParameter.FAMILY_TOP_LEVEL_OFFSET_PARAM).Set((zt - lz) / f);
  fi.get_Parameter(BuiltInParameter.FAMILY_BASE_LEVEL_OFFSET_PARAM).Set((zb - lz) / f);
  doc.Regenerate();
  ElementTransformUtils.RotateElement(doc, fi.Id, Line.CreateBound(pt, pt + XYZ.BasisZ), ang * Math.PI / 180);
  fi.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.Set(id);
  fi.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS)?.Set(Tama.Args.Get(args, "comment", ""));
  doc.Regenerate();
  var bb = fi.get_BoundingBox(null); var lp = (LocationPoint)fi.Location;
  outp.Add(new { id, elementId = fi.Id.IntegerValue, at = new[] { Math.Round(lp.Point.X * f, 4), Math.Round(lp.Point.Y * f, 4) },
    rot = Math.Round(lp.Rotation * 180 / Math.PI, 2), zMin = Math.Round(bb.Min.Z * f, 3), zMax = Math.Round(bb.Max.Z * f, 3),
    height = Math.Round(zt - zb, 4) });
}
return new { levelElevation = Math.Round(lz, 4), placed = outp };
